      pa: '$1000\\text{ mL}$ ($1\\text{ L}$) ਘੋਲ ਲਈ: ਘੋਲ ਦਾ ਪੁੰਜ $= 1000 \\times 1.194 = 1194\\text{ g}$। $\\text{H}_2\\text{SO}_4$ ਦੇ ਮੋਲ $= 3.0\\text{ mol}$, ਘੁਲਣਸ਼ੀਲ ਦਾ ਪੁੰਜ $= 3.0 \\times 98 = 294\\text{ g}$। ਘੋਲਕ (ਪਾਣੀ) ਦਾ ਪੁੰਜ $= 1194 - 294 = 900\\text{ g} = 0.900\\text{ kg}$। ਮੋਲੈਲਿਟੀ $m = \\frac{3.0}{0.900} = 3.33\\text{ mol kg}^{-1}$। ਮੋਲੈਲਿਟੀ ਤਾਪਮਾਨ ਤੋਂ ਸੁਤੰਤਰ ਹੁੰਦੀ ਹੈ।',
