      pa: 'MOT ਅਨੁਸਾਰ ($\\text{Bond Order} = \\frac{N_b - N_a}{2}$): $\\text{O}_2^+$ ($15e^-$) ਦਾ $\\text{BO} = 2.5$ ($1$ ਅਣਜੋੜਿਆ ਇਲੈਕਟ੍ਰਾਨ, ਪੈਰਾਮੈਗਨੈਟਿਕ); $\\text{O}_2$ ($16e^-$) ਦਾ $\\text{BO} = 2.0$ ($2$ ਅਣਜੋੜੇ ਇਲੈਕਟ੍ਰਾਨ, ਪੈਰਾਮੈਗਨੈਟਿਕ); $\\text{O}_2^-$ ($17e^-$) ਦਾ $\\text{BO} = 1.5$ ($1$ ਅਣਜੋੜਿਆ ਇਲੈਕਟ੍ਰਾਨ); ਅਤੇ $\\text{O}_2^{2-}$ ($18e^-$) ਦਾ $\\text{BO} = 1.0$ ($0$ ਅਣਜੋੜੇ ਇਲੈਕਟ੍ਰਾਨ, ਡਾਇਆਮੈਗਨੈਟਿਕ) ਹੈ।',
      hi: 'MOT के अनुसार ($\\text{आबंध कोटि} = \\frac{N_b - N_a}{2}$): $\\text{O}_2^+$ ($15e^-$) की आबंध कोटि $= 2.5$ ($1$ अयुग्मित इलेक्ट्रॉन, अनुचुंबकीय); $\\text{O}_2$ ($16e^-$) की आबंध कोटि $= 2.0$ ($2$ अयुग्मित इलेक्ट्रॉन, अनुचुंबकीय); $\\text{O}_2^-$ ($17e^-$) की आबंध कोटि $= 1.5$ ($1$ अयुग्मित इलेक्ट्रॉन); तथा $\\text{O}_2^{2-}$ ($18e^-$) की आबंध कोटि $= 1.0$ ($0$ अयुग्मित इलेक्ट्रॉन, प्रतिचुंबकीय) है।',
