    correct: 'B',
    explanation: {
      en: 'For the cell reaction $\\text{Zn}(s) + \\text{Cu}^{2+}(aq) \\rightarrow \\text{Zn}^{2+}(aq) + \\text{Cu}(s)$, $n = 2$ and $Q = \\frac{[\\text{Zn}^{2+}]}{[\\text{Cu}^{2+}]} = \\frac{0.1}{0.001} = 10^2$. By the Nernst equation: $E_{\\text{cell}} = E^\\circ_{\\text{cell}} - \\frac{0.0591}{2}\\log_{10}(10^2) = 1.10 - \\frac{0.0591}{2}(2) = 1.10 - 0.0591 = 1.0409\\text{ V}$.',
      pa: 'ਸੈੱਲ ਪ੍ਰਤੀਕਿਰਿਆ $\\text{Zn}(s) + \\text{Cu}^{2+}(aq) \\rightarrow \\text{Zn}^{2+}(aq) + \\text{Cu}(s)$ ਲਈ, $n = 2$ ਅਤੇ $Q = \\frac{[\\text{Zn}^{2+}]}{[\\text{Cu}^{2+}]} = \\frac{0.1}{0.001} = 10^2$ ਹੈ। ਨਰਨਸਟ ਸਮੀਕਰਨ ਅਨੁਸਾਰ: $E_{\\text{cell}} = 1.10 - \\frac{0.0591}{2}\\log_{10}(10^2) = 1.10 - 0.0591 = 1.0409\\text{ V}$।',
      hi: 'सेल अभिक्रिया $\\text{Zn}(s) + \\text{Cu}^{2+}(aq) \\rightarrow \\text{Zn}^{2+}(aq) + \\text{Cu}(s)$ के लिए, $n = 2$ और $Q = \\frac{[\\text{Zn}^{2+}]}{[\\text{Cu}^{2+}]} = \\frac{0.1}{0.001} = 10^2$ है। नेर्नस्ट समीकरण के अनुसार: $E_{\\text{cell}} = 1.10 - \\frac{0.0591}{2}\\log_{10}(10^2) = 1.10 - 0.0591 = 1.0409\\text{ V}$।',
    },
