      pa: '$298\\text{ K}$ ਤੇ ਸੀਮਾਂਤ ਮੋਲਰ ਚਾਲਕਤਾਵਾਂ ($\\Lambda_m^\\circ$) ਦਿੱਤੀਆਂ ਗਈਆਂ ਹਨ: $\\Lambda_m^\\circ(\\text{CH}_3\\text{COONa}) = 91.0\\text{ S cm}^2\\text{ mol}^{-1}$, $\\Lambda_m^\\circ(\\text{HCl}) = 425.9\\text{ S cm}^2\\text{ mol}^{-1}$ ਅਤੇ $\\Lambda_m^\\circ(\\text{NaCl}) = 126.4\\text{ S cm}^2\\text{ mol}^{-1}$। ਕੋਲਰਾਸ਼ ਦੇ ਨਿਯਮ ਅਨੁਸਾਰ $\\Lambda_m^\\circ(\\text{CH}_3\\text{COOH})$ ਦਾ ਮੁੱਲ ਕੀ ਹੈ?',
