      pa: 'ਪਹਿਲੇ ਦਰਜੇ ਦੀ ਪ੍ਰਤੀਕਿਰਿਆ ਲਈ: $t_{99.9\\%} = \\frac{2.303}{k}\\log_{10}(10^3) = \\frac{2.303 \\times 3}{k}$ ਅਤੇ $t_{1/2} = \\frac{2.303 \\times 0.300}{k}$। ਦੋਵਾਂ ਨੂੰ ਭਾਗ ਕਰਨ ਤੇ $\\frac{t_{99.9\\%}}{t_{1/2}} = \\frac{3}{0.300} = 10$ ਮਿਲਦਾ ਹੈ। ਇਸ ਲਈ $t_{99.9\\%} = 10 \\times 15.0 = 150\\text{ min}$।',
