        pa: '$\\%T = 10\\%$; ਕੰਪਨ ਨਾਲ ਡਾਇਪੋਲ ਮੋਮੈਂਟ ਵਿੱਚ ਪਰਿਵਰਤਨ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ ($\\frac{d\\mu}{dq} \\neq 0$)',
        hi: '$\\%T = 10\\%$; कंपन से द्विध्रुव आघूर्ण में परिवर्तन होना चाहिए ($\\frac{d\\mu}{dq} \\neq 0$)',
