      hi: '$\\text{La}^{3+}$ से $\\text{Lu}^{3+}$ तक $4f$ श्रेणी में लैंथेनॉयड संकुचन ($4f$ इलेक्ट्रॉनों द्वारा दुर्बल परिरक्षण) के दो प्रमुख रासायनिक परिणाम क्या हैं?',
