        hi: '$\\text{Zr}$ से $\\text{Hf}$ तक त्रिज्या में बड़ी वृद्धि, तथा $\\text{La(OH)}_3$ से $\\text{Lu(OH)}_3$ तक क्षारीय सामर्थ्य का बढ़ना',
