      en: 'Although both $\\text{Mn(VII)}$ in $\\text{MnO}_4^-$ (intense purple) and $\\text{Cr(VI)}$ in $\\text{Cr}_2\\text{O}_7^{2-}$ (intense orange) have a $3d^0$ electronic configuration with zero $d$ electrons, they are intensely coloured. What is the electronic origin of their colour?',
