    correct: 'D',
    explanation: {
      en: 'A higher negative charge (lower oxidation state) on the central metal increases electron density available for $M(d\\pi) \\rightarrow \\text{CO}(\\pi^*)$ back-donation. Greater population of the antibonding $\\pi^*$ orbital of $\\text{CO}$ strengthens the $\\text{M}-\\text{C}$ bond and weakens the $\\text{C}-\\text{O}$ bond, lowering $\\bar{\\nu}_{\\text{CO}}$. Since the metal oxidation states are $\\text{V}(-1) < \\text{Cr}(0) < \\text{Mn}(+1)$, $\\pi$-backbonding decreases in the order $[\\text{V(CO)}_6]^- > [\\text{Cr(CO)}_6] > [\\text{Mn(CO)}_6]^+$, so $\\bar{\\nu}_{\\text{CO}}$ increases in the order $[\\text{V(CO)}_6]^-\\ (1860\\text{ cm}^{-1}) < [\\text{Cr(CO)}_6]\\ (2000\\text{ cm}^{-1}) < [\\text{Mn(CO)}_6]^+\\ (2090\\text{ cm}^{-1})$.',
      pa: 'ਧਾਤੂ ਤੇ ਜਿੰਨਾ ਵੱਧ ਰਿਣਾਤਮਕ ਚਾਰਜ ਹੁੰਦਾ ਹੈ, $M(d\\pi) \\rightarrow \\text{CO}(\\pi^*)$ ਬੈਕ-ਡੋਨੇਸ਼ਨ ਓਨੀ ਹੀ ਜ਼ਿਆਦਾ ਹੁੰਦੀ ਹੈ। $\\text{CO}$ ਦੇ ਐਂਟੀਬਾਂਡਿੰਗ $\\pi^*$ ਆਰਬਿਟਲ ਵਿੱਚ ਇਲੈਕਟ੍ਰਾਨ ਜਾਣ ਨਾਲ $\\text{C}-\\text{O}$ ਬਾਂਡ ਕਮਜ਼ੋਰ ਹੁੰਦਾ ਹੈ ਅਤੇ $\\bar{\\nu}_{\\text{CO}}$ ਘਟਦਾ ਹੈ। ਇਸ ਲਈ $\\bar{\\nu}_{\\text{CO}}$ ਦਾ ਵਧਦਾ ਕ੍ਰਮ $[\\text{V(CO)}_6]^- < [\\text{Cr(CO)}_6] < [\\text{Mn(CO)}_6]^+$ ਹੈ।',
      hi: 'केंद्रीय धातु पर ऋणावेश जितना अधिक होता है, $M(d\\pi) \\rightarrow \\text{CO}(\\pi^*)$ पश्च-दान उतना ही अधिक होता है। $\\text{CO}$ के प्रति-आबंधी $\\pi^*$ कक्षक में इलेक्ट्रॉन घनत्व बढ़ने से $\\text{C}-\\text{O}$ आबंध कोटि घटती है और $\\bar{\\nu}_{\\text{CO}}$ कम हो जाता है। अतः $\\bar{\\nu}_{\\text{CO}}$ का बढ़ता क्रम $[\\text{V(CO)}_6]^- < [\\text{Cr(CO)}_6] < [\\text{Mn(CO)}_6]^+$ है।',
    },
