        hi: '$\\text{cis-}$ और $\\text{trans-}[\\text{Pt(NH}_3)_2\\text{Cl}_2]$ दोनों समान रूप से सक्रिय हैं क्योंकि वे रक्त प्लाज्मा में तेजी से अंतर-रूपांतरित होते हैं',
