    correct: 'D',
    explanation: {
      en: 'Only $\\alpha$-decay changes the mass number $A$ (by $4$ units per $\\alpha$-particle): $n_\\alpha = \\frac{232 - 208}{4} = \\frac{24}{4} = 6$. Each $\\alpha$-decay decreases the atomic number $Z$ by $2$, whereas each $\\beta^-$-decay increases $Z$ by $1$: $90 - 2(6) + n_\\beta = 82 \\implies 78 + n_\\beta = 82 \\implies n_\\beta = 4$. Thus $6\\ \\alpha$ and $4\\ \\beta^-$ particles are emitted.',
      pa: 'ਕੇਵਲ $\\alpha$-ਖੈ ਪੁੰਜ ਸੰਖਿਆ $A$ ਨੂੰ ਬਦਲਦਾ ਹੈ: $n_\\alpha = \\frac{232 - 208}{4} = \\frac{24}{4} = 6$। ਪਰਮਾਣੂ ਕ੍ਰਮਾਂਕ $Z$ ਦੇ ਸੰਤੁਲਨ ਤੋਂ: $90 - 2(6) + n_\\beta = 82 \\implies 78 + n_\\beta = 82 \\implies n_\\beta = 4$। ਇਸ ਲਈ $6\\ \\alpha$ ਅਤੇ $4\\ \\beta^-$ ਕਣ ਨਿਕਲਦੇ ਹਨ।',
      hi: 'केवल $\\alpha$-क्षय द्रव्यमान संख्या $A$ को बदलता है: $n_\\alpha = \\frac{232 - 208}{4} = \\frac{24}{4} = 6$। परमाणु क्रमांक $Z$ के संतुलन से: $90 - 2(6) + n_\\beta = 82 \\implies 78 + n_\\beta = 82 \\implies n_\\beta = 4$। अतः $6\\ \\alpha$ और $4\\ \\beta^-$ कण उत्सर्जित होते हैं।',
    },
