      en: 'In Kjeldahl\'s method, organic nitrogen is digested with conc. $\\text{H}_2\\text{SO}_4$ (with $\\text{CuSO}_4$ catalyst and $\\text{K}_2\\text{SO}_4$) to form ammonium sulphate, $(\\text{NH}_4)_2\\text{SO}_4$. Compounds containing nitrogen in nitro ($-\\text{NO}_2$), azo ($-\\text{N}=\\text{N}-$), or diazo groups, or nitrogen present in an aromatic ring (such as pyridine or quinoline), do not quantitatively convert to $(\\text{NH}_4)_2\\text{SO}_4$; for those, Dumas\' method (measuring $\\text{N}_2$ gas) is used.',
      pa: 'ਜੇਲਡਾਲ ਵਿਧੀ ਵਿੱਚ ਜੈਵਿਕ ਨਾਈਟ੍ਰੋਜਨ ਨੂੰ ਗਾੜ੍ਹੇ $\\text{H}_2\\text{SO}_4$ ਨਾਲ ਗਰਮ ਕਰਕੇ ਅਮੋਨੀਅਮ ਸਲਫੇਟ $(\\text{NH}_4)_2\\text{SO}_4$ ਵਿੱਚ ਬਦਲਿਆ ਜਾਂਦਾ ਹੈ। ਨਾਈਟ੍ਰੋ ($-\\text{NO}_2$), ਐਜ਼ੋ ($-\\text{N}=\\text{N}-$) ਜਾਂ ਰਿੰਗ ਵਿੱਚ ਮੌਜੂਦ ਨਾਈਟ੍ਰੋਜਨ (ਜਿਵੇਂ ਪਿਰੀਡੀਨ) ਇਸ ਵਿਧੀ ਨਾਲ $(\\text{NH}_4)_2\\text{SO}_4$ ਵਿੱਚ ਨਹੀਂ ਬਦਲਦੇ; ਉਹਨਾਂ ਲਈ ਡੂਮਾਸ (Dumas) ਵਿਧੀ ਵਰਤੀ ਜਾਂਦੀ ਹੈ।',
