      pa: 'ਹਿਊਕਲ (Hückel) ਦੇ ਐਰੋਮੈਟਿਕਤਾ ਨਿਯਮ ਦੇ ਅਨੁਸਾਰ, ਹੇਠ ਲਿਖੀਆਂ ਸਮਤਲੀ ਚੱਕਰੀ ਸਪੀਸੀਜ਼ ਦਾ ਵਰਗੀਕਰਨ ਕਰੋ: (i) ਟ੍ਰੋਪੀਲੀਅਮ ਕੈਟਾਇਨ ($\\text{C}_7\\text{H}_7^+$), (ii) ਸਾਈਕਲੋਪੈਂਟਾਡਾਇਨਾਈਲ ਐਨਾਇਨ ($\\text{C}_5\\text{H}_5^-$), ਅਤੇ (iii) ਸਾਈਕਲੋਬਿਊਟਾਡਾਈਨ ($\\text{C}_4\\text{H}_4$)।',
