        pa: '(i) $1$-ਬ੍ਰੋਮੋਪ੍ਰੋਪੇਨ (ਐਂਟੀ-ਮਾਰਕੋਵਨੀਕੋਵ) ਅਤੇ (ii) $2$-ਕਲੋਰੋਪ੍ਰੋਪੇਨ (ਮਾਰਕੋਵਨੀਕੋਵ, ਕਿਉਂਕਿ $\\text{H}-\\text{Cl}$ ਬਾਂਡ ਬਹੁਤ ਮਜ਼ਬੂਤ ਹੈ ਅਤੇ ਇਸਦਾ ਰੈਡੀਕਲ ਪ੍ਰੋਪੇਗੇਸ਼ਨ ਪੜਾਅ ਐਂਡੋਥਰਮਿਕ ਹੁੰਦਾ ਹੈ)',
