      pa: 'ਲਿੰਡਲਾਰ ਕੈਟਾਲਿਸਟ ਉੱਤੇ ਹਾਈਡ੍ਰੋਜਨੀਕਰਨ ਨਾਲ ਦੋਵੇਂ ਹਾਈਡ੍ਰੋਜਨ ਪਰਮਾਣੂ ਇੱਕੋ ਪਾਸੇ ਤੋਂ ਜੁੜਦੇ ਹਨ (ਸਿਨ-ਜੋੜ), ਜਿਸ ਨਾਲ $\\text{cis}$-ਬਿਊਟ-$2$-ਈਨ ਬਣਦੀ ਹੈ। ਇਸ ਦੇ ਉਲਟ, ਤਰਲ $\\text{NH}_3$ ਵਿੱਚ $\\text{Na}$ (ਬਰਚ ਰਿਡਕਸ਼ਨ) ਰੈਡੀਕਲ ਐਨਾਇਨ ਇੰਟਰਮੀਡੀਏਟ ਰਾਹੀਂ ਐਂਟੀ-ਜੋੜ ਕਰਵਾ ਕੇ $\\text{trans}$-ਬਿਊਟ-$2$-ਈਨ ਦਿੰਦਾ ਹੈ।',
