    correct: 'B',
    explanation: {
      en: 'Aldol condensation requires at least one acidic $\\alpha$-hydrogen atom to form an enolate nucleophile. Since neither $\\text{HCHO}$ nor $\\text{C}_6\\text{H}_5\\text{CHO}$ possesses an $\\alpha$-hydrogen, they undergo base-induced disproportionation (Cannizzaro reaction). In the Cross-Cannizzaro reaction, $\\text{OH}^-$ attacks the more electrophilic, less hindered carbonyl of $\\text{HCHO}$ first, which then transfers a hydride ion ($\\text{H}^-$) to $\\text{C}_6\\text{H}_5\\text{CHO}$, oxidizing $\\text{HCHO}$ to sodium formate ($\\text{HCOONa}$) and reducing $\\text{C}_6\\text{H}_5\\text{CHO}$ to benzyl alcohol ($\\text{C}_6\\text{H}_5\\text{CH}_2\\text{OH}$).',
      pa: 'ਐਲਡੋਲ ਕੰਡੈਂਸੇਸ਼ਨ ਲਈ ਘੱਟੋ-ਘੱਟ ਇੱਕ $\\alpha$-ਹਾਈਡ੍ਰੋਜਨ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਕਿਉਂਕਿ $\\text{HCHO}$ ਅਤੇ $\\text{C}_6\\text{H}_5\\text{CHO}$ ਦੋਵਾਂ ਵਿੱਚ ਕੋਈ $\\alpha$-ਹਾਈਡ੍ਰੋਜਨ ਨਹੀਂ ਹੈ, ਉਹ ਕੈਨੀਜ਼ਾਰੋ ਪ੍ਰਤੀਕਿਰਿਆ ਦਿੰਦੇ ਹਨ। ਕਰਾਸ-ਕੈਨੀਜ਼ਾਰੋ ਪ੍ਰਤੀਕਿਰਿਆ ਵਿੱਚ ਵੱਧ ਇਲੈਕਟ੍ਰੋਫਿਲਿਕ $\\text{HCHO}$ ਦਾ ਆਕਸੀਕਰਨ ਹੋ ਕੇ ਸੋਡੀਅਮ ਫਾਰਮੇਟ ($\\text{HCOONa}$) ਬਣਦਾ ਹੈ ਅਤੇ $\\text{C}_6\\text{H}_5\\text{CHO}$ ਦਾ ਲਘੂਕਰਨ ਹੋ ਕੇ ਬੈਂਜ਼ਾਈਲ ਅਲਕੋਹਲ ($\\text{C}_6\\text{H}_5\\text{CH}_2\\text{OH}$) ਬਣਦਾ ਹੈ।',
      hi: 'एल्डोल संघनन के लिए कम से कम एक अम्लीय $\\alpha$-हाइड्रोजन आवश्यक है। चूँकि $\\text{HCHO}$ और $\\text{C}_6\\text{H}_5\\text{CHO}$ दोनों में $\\alpha$-हाइड्रोजन नहीं होता, वे कैनिज़ारो असमानुपातन अभिक्रिया देते हैं। क्रॉस-कैनिज़ारो अभिक्रिया में अधिक इलेक्ट्रॉनरागी $\\text{HCHO}$ ऑक्सीकृत होकर सोडियम फॉर्मेट ($\\text{HCOONa}$) बनाता है तथा $\\text{C}_6\\text{H}_5\\text{CHO}$ हाइड्राइड स्थानांतरण द्वारा अपचयित होकर बेंज़िल अल्कोहल ($\\text{C}_6\\text{H}_5\\text{CH}_2\\text{OH}$) बनाता है।',
    },
