    explanation: {
      en: 'In the gas phase, only the $+I$ effect operates, giving $3^\\circ > 2^\\circ > 1^\\circ > \\text{NH}_3$. In aqueous solution, hydration stabilization of the conjugate acid ($\\text{RNH}_3^+ > \\text{R}_2\\text{NH}_2^+ > \\text{R}_3\\text{NH}^+$) opposes the $+I$ effect. For the bulkier ethyl group, the stronger $+I$ effect makes $3^\\circ$ more basic than $1^\\circ$: $2^\\circ > 3^\\circ > 1^\\circ > \\text{NH}_3$ (code: 231). For the smaller methyl group, solvation outweighs the weaker $+I$ effect between $1^\\circ$ and $3^\\circ$, giving $2^\\circ > 1^\\circ > 3^\\circ > \\text{NH}_3$ (code: 213).',
      pa: 'ਗੈਸ ਅਵਸਥਾ ਵਿੱਚ ਕੇਵਲ $+I$ ਪ੍ਰਭਾਵ ਕਾਰਨ ਕ੍ਰਮ $3^\\circ > 2^\\circ > 1^\\circ > \\text{NH}_3$ ਹੁੰਦਾ ਹੈ। ਪਰ ਜਲੀ ਘੋਲ ਵਿੱਚ $+I$ ਪ੍ਰਭਾਵ, ਹਾਈਡ੍ਰੋਜਨ ਬਾਂਡਿੰਗ (ਸੋਲਵੇਸ਼ਨ) ਅਤੇ ਸਟੇਰਿਕ ਰੁਕਾਵਟ ਕਾਰਨ: (i) ਈਥਾਈਲਅਮੀਨਾਂ ਲਈ ਕ੍ਰਮ $2^\\circ > 3^\\circ > 1^\\circ > \\text{NH}_3$ (231) ਹੁੰਦਾ ਹੈ, ਅਤੇ (ii) ਮਿਥਾਈਲਅਮੀਨਾਂ ਲਈ ਕ੍ਰਮ $2^\\circ > 1^\\circ > 3^\\circ > \\text{NH}_3$ (213) ਹੁੰਦਾ ਹੈ।',
      hi: 'गैस प्रावस्था में केवल $+I$ प्रभाव के कारण क्रम $3^\\circ > 2^\\circ > 1^\\circ > \\text{NH}_3$ होता है। किंतु जलीय विलयन में $+I$ प्रभाव, जलयोजन (H-आबंधन) और त्रिविम बाधा के परिणामी प्रभाव से: (i) एथिलऐमीनों के लिए क्रम $2^\\circ > 3^\\circ > 1^\\circ > \\text{NH}_3$ (231) तथा (ii) मेथिलऐमीनों के लिए क्रम $2^\\circ > 1^\\circ > 3^\\circ > \\text{NH}_3$ (213) होता है।',
    },
