    explanation: {
      en: 'In Experiment I, $\\text{NaBH}_4$ is a mild, chemoselective hydride donor that reduces aldehydes, ketones, and acyl chlorides, but does NOT reduce esters; hence only the ketone is reduced to give ethyl $4$-hydroxypentanoate. In Experiment II, the more reactive ketone selectively forms a base-stable cyclic ketal ($1,3$-dioxolane) with ethylene glycol; $\\text{LiAlH}_4$ then reduces the remaining ester to $-\\text{CH}_2\\text{OH}$, and final acidic hydrolysis ($\\text{H}_3\\text{O}^+$) deprotects the ketal back to the ketone, yielding $5$-hydroxypentan-$2$-one.',
      pa: 'ਪ੍ਰਯੋਗ I ਵਿੱਚ, $\\text{NaBH}_4$ ਚੋਣਵੇਂ ਤੌਰ ਤੇ ਕੇਵਲ ਕੀਟੋਨ ਸਮੂਹ ਦਾ ਲਘੂਕਰਨ ਕਰਦਾ ਹੈ ਅਤੇ ਐਸਟਰ ਸਮੂਹ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਨਹੀਂ ਕਰਦਾ, ਜਿਸ ਨਾਲ ਈਥਾਈਲ $4$-ਹਾਈਡ੍ਰੋਕਸੀਪੈਂਟਾਨੋਏਟ ਬਣਦਾ ਹੈ। ਪ੍ਰਯੋਗ II ਵਿੱਚ, ਈਥਾਈਲੀਨ ਗਲਾਈਕੋਲ ਪਹਿਲਾਂ ਵੱਧ ਕਿਰਿਆਸ਼ੀਲ ਕੀਟੋਨ ਨੂੰ ਚੱਕਰੀ ਕੀਟਲ (acetal/ketal) ਵਜੋਂ ਸੁਰੱਖਿਅਤ ਕਰਦਾ ਹੈ, ਫਿਰ $\\text{LiAlH}_4$ ਐਸਟਰ ਨੂੰ $-\\text{CH}_2\\text{OH}$ ਵਿੱਚ ਬਦਲਦਾ ਹੈ, ਅਤੇ $\\text{H}_3\\text{O}^+$ ਕੀਟਲ ਨੂੰ ਵਾਪਸ ਕੀਟੋਨ ਵਿੱਚ ਬਦਲ ਕੇ $5$-ਹਾਈਡ੍ਰੋਕਸੀਪੈਂਟੇਨ-$2$-ਓਨ ਦਿੰਦਾ ਹੈ।',
      hi: 'प्रयोग I में, $\\text{NaBH}_4$ एक मृदु, रसायन-चयनात्मक अपचायक है जो केवल कीटोन को अपचयित करता है और एस्टर को प्रभावित नहीं करता, जिससे एथिल $4$-हाइड्रॉक्सीपेंटेनोएट बनता है। प्रयोग II में, एथिलीन ग्लाइकॉल अधिक क्रियाशील कीटोन को चक्रीय कीटल के रूप में सुरक्षित करता है, तत्पश्चात $\\text{LiAlH}_4$ एस्टर को $-\\text{CH}_2\\text{OH}$ में अपचयित करता है, और $\\text{H}_3\\text{O}^+$ विरक्षण द्वारा $5$-हाइड्रॉक्सीपेंटेन-$2$-ओन देता है।',
    },
