      en: 'Butan-$2$-one has $3$ chemically non-equivalent sets of protons ($a, b, c$). By the $(n + 1)$ spin-spin splitting rule: (1) $\\text{CH}_3^{(a)}$ has $n = 0$ vicinal protons across the carbonyl carbon, giving a $3\\text{H}$ singlet ($\\delta \\approx 2.1\\text{ ppm}$). (2) $\\text{CH}_2^{(b)}$ is coupled to the $3$ equivalent protons of $\\text{CH}_3^{(c)}$ ($n = 3$), splitting into a $2\\text{H}$ quartet ($n + 1 = 4$, Pascal intensity ratio $1:3:3:1$, $\\delta \\approx 2.4\\text{ ppm}$). (3) $\\text{CH}_3^{(c)}$ is coupled to the $2$ protons of $\\text{CH}_2^{(b)}$ ($n = 2$), splitting into a $3\\text{H}$ triplet ($n + 1 = 3$, ratio $1:2:1$, $\\delta \\approx 1.0\\text{ ppm}$).',
      pa: 'ਬਿਊਟੇਨ-$2$-ਓਨ ਵਿੱਚ ਪ੍ਰੋਟੋਨਾਂ ਦੇ $3$ ਰਸਾਇਣਕ ਤੌਰ ਤੇ ਵੱਖਰੇ ਸੈੱਟ ($a, b, c$) ਹਨ। $(n + 1)$ ਨਿਯਮ ਅਨੁਸਾਰ: (1) $\\text{CH}_3^{(a)}$ ਦੇ ਗੁਆਂਢ ਵਿੱਚ ਕੋਈ ਪ੍ਰੋਟੋਨ ਨਹੀਂ ਹੈ ($n = 0$), ਇਸ ਲਈ $3\\text{H}$ ਸਿੰਗਲੈੱਟ ਮਿਲਦਾ ਹੈ। (2) $\\text{CH}_2^{(b)}$ ਗੁਆਂਢੀ $\\text{CH}_3^{(c)}$ ਦੇ $3$ ਪ੍ਰੋਟੋਨਾਂ ($n = 3$) ਕਾਰਨ $2\\text{H}$ ਕੁਆਰਟੈੱਟ ($1:3:3:1$) ਵਿੱਚ ਵੰਡਿਆ ਜਾਂਦਾ ਹੈ। (3) $\\text{CH}_3^{(c)}$ ਗੁਆਂਢੀ $\\text{CH}_2^{(b)}$ ਦੇ $2$ ਪ੍ਰੋਟੋਨਾਂ ($n = 2$) ਕਾਰਨ $3\\text{H}$ ਟ੍ਰਿਪਲੈੱਟ ($1:2:1$) ਦਿੰਦਾ ਹੈ।',
