    correct: 'D',
    explanation: {
      en: 'Bromine water ($\\text{Br}_2 / \\text{H}_2\\text{O}$) is a mild, selective oxidizing agent that oxidizes only the C-1 aldehyde group ($-\\text{CHO}$) of $\\text{D}$-glucose (without oxidizing the primary alcohol or ketoses like $\\text{D}$-fructose) to form the six-carbon monocarboxylic acid, $\\text{D}$-gluconic acid ($\\text{HOCH}_2(\\text{CHOH})_4\\text{COOH}$). Concentrated $\\text{HNO}_3$ is a strong oxidizing agent that oxidizes both the C-1 $-\\text{CHO}$ group and the terminal C-6 primary alcohol ($-\\text{CH}_2\\text{OH}$) group to yield the dicarboxylic acid, $\\text{D}$-saccharic (glucaric) acid ($\\text{HOOC}(\\text{CHOH})_4\\text{COOH}$).',
      pa: 'ਬ੍ਰੋਮੀਨ ਪਾਣੀ ($\\text{Br}_2 / \\text{H}_2\\text{O}$) ਇੱਕ ਹਲਕਾ ਆਕਸੀਕਾਰਕ ਹੈ ਜੋ $\\text{D}$-ਗਲੂਕੋਜ਼ ਦੇ ਕੇਵਲ C-1 ਐਲਡੀਹਾਈਡ ਸਮੂਹ ($-\\text{CHO}$) ਨੂੰ ਆਕਸੀਕ੍ਰਿਤ ਕਰਕੇ $\\text{D}$-ਗਲੂਕੋਨਿਕ ਐਸਿਡ ਬਣਾਉਂਦਾ ਹੈ। ਗਾੜ੍ਹਾ $\\text{HNO}_3$ ਇੱਕ ਤੀਬਰ ਆਕਸੀਕਾਰਕ ਹੈ ਜੋ C-1 $-\\text{CHO}$ ਅਤੇ C-6 ਪ੍ਰਾਇਮਰੀ ਅਲਕੋਹਲ ($-\\text{CH}_2\\text{OH}$) ਦੋਵਾਂ ਨੂੰ ਆਕਸੀਕ੍ਰਿਤ ਕਰਕੇ ਡਾਈਕਾਰਬੋਕਸਿਲਿਕ ਐਸਿਡ, $\\text{D}$-ਸੈਕਰਿਕ ਐਸਿਡ, ਬਣਾਉਂਦਾ ਹੈ।',
      hi: 'ब्रोमीन जल ($\\text{Br}_2 / \\text{H}_2\\text{O}$) एक मृदु ऑक्सीकारक है जो $\\text{D}$-ग्लूकोज़ के केवल C-1 एल्डिहाइड समूह ($-\\text{CHO}$) को ऑक्सीकृत करके $\\text{D}$-ग्लूकोनिक अम्ल बनाता है। सांद्र $\\text{HNO}_3$ एक प्रबल ऑक्सीकारक है जो C-1 $-\\text{CHO}$ और C-6 प्राथमिक अल्कोहल ($-\\text{CH}_2\\text{OH}$) दोनों को ऑक्सीकृत करके डाइकार्बोक्सिलिक अम्ल, $\\text{D}$-सैकेरिक अम्ल, बनाता है।',
    },
